public class Car {private int id,year;private String make,model,color,registration;private double price;public Car(int id,String make,String model,int year,String color,double price,String registration){this.id=id;this.make=make;this.model=model;this.year=year;this.color=color;this.price=price;this.registration=registration;}public Car(int id,String make,String model){this(id,make,model,2000,"black",0,"X");}public int id(){return id;}public void id(int x){id=x;}public int year(){return year;}public void year(int x){year=x;}public String make(){return make;}public void make(String x){make=x;}public String model(){return model;}public void model(String x){model=x;}public String color(){return color;}public void color(String x){color=x;}public double price(){return price;}public void price(double x){price=x;}public String registration(){return registration;}public void registration(String x){registration=x;}public String toString(){return id+":"+make+":"+model+":"+year+":"+color+":"+price+":"+registration;}public static Car[] make(Car[]a,String s){return java.util.Arrays.stream(a).filter(c->c.make.equals(s)).toArray(Car[]::new);}public static Car[] older(Car[]a,String s,int now,int n){return java.util.Arrays.stream(a).filter(c->c.model.equals(s)&&now-c.year>n).toArray(Car[]::new);}public static Car[] dearer(Car[]a,int y,double p){return java.util.Arrays.stream(a).filter(c->c.year==y&&c.price>p).toArray(Car[]::new);}}
